import{_ as t}from"./chunks/website-studio.B1ViRGxP.js";import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const b=JSON.parse('{"title":"Επισκόπηση Website Studio","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/studio-overview.md","filePath":"el/websites/studio-overview.md"}'),s={name:"el/websites/studio-overview.md"};function l(d,e,n,c,h,p){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="επισκοπηση-website-studio" tabindex="-1">Επισκόπηση Website Studio <a class="header-anchor" href="#επισκοπηση-website-studio" aria-label="Permalink to &quot;Επισκόπηση Website Studio&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/website-studio.png"><img src="'+t+'" alt="Website Studio: δομή σελίδων αριστερά, προσαρμοζόμενος καμβάς στο κέντρο και ιδιότητες δεξιά. Εμφανίζεται αποθηκευμένο τοπικό προσχέδιο, όχι δημοσιευμένος ιστότοπος."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Website Studio: δομή σελίδων αριστερά, προσαρμοζόμενος καμβάς στο κέντρο και ιδιότητες δεξιά. Εμφανίζεται αποθηκευμένο τοπικό προσχέδιο, όχι δημοσιευμένος ιστότοπος.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><h2 id="σκοπος-και-προσβαση" tabindex="-1">Σκοπός και πρόσβαση <a class="header-anchor" href="#σκοπος-και-προσβαση" aria-label="Permalink to &quot;Σκοπός και πρόσβαση&quot;">​</a></h2><p>Το Website Studio είναι ο οπτικός επεξεργαστής πολλαπλών σελίδων του TransferBook+. Στον κώδικα αναφοράς ανοίξτε <strong>Channels &amp; Governance → Website Studio</strong> ή επιλέξτε Website Studio από <strong>Settings → Website &amp; Themes</strong>. Χρησιμοποιήστε εξουσιοδοτημένο εταιρικό περιβάλλον. Το ανεξάρτητο εργαλείο σχεδιασμού λειτουργεί χωριστά.</p><h2 id="τα-τρια-πανελ" tabindex="-1">Τα τρία πάνελ <a class="header-anchor" href="#τα-τρια-πανελ" aria-label="Permalink to &quot;Τα τρία πάνελ&quot;">​</a></h2><ol><li>Αριστερά: ιστοσελίδες, αγορές, σελίδες, ενότητες και πλοήγηση.</li><li>Κέντρο: προεπισκόπηση της επιλεγμένης σελίδας και διάταξη ενοτήτων.</li><li>Δεξιά: ρυθμίσεις ενότητας, Page &amp; SEO, Design, Brand &amp; Markets και History.</li></ol><h2 id="ασφαλης-εναρξη" tabindex="-1">Ασφαλής έναρξη <a class="header-anchor" href="#ασφαλης-εναρξη" aria-label="Permalink to &quot;Ασφαλής έναρξη&quot;">​</a></h2><p>Επιλέξτε συνθετικό πρότυπο ή επιτρεπόμενο προσχέδιο. Επιβεβαιώστε την εταιρεία και επιλέξτε σελίδα και συσκευή προεπισκόπησης. Τα ενσωματωμένα παραδείγματα δεν αποτελούν επαληθευμένες εμπορικές ιστοσελίδες.</p><h2 id="αποτελεσμα-και-αντιμετωπιση-προβληματων" tabindex="-1">Αποτέλεσμα και αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αποτελεσμα-και-αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αποτέλεσμα και αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Το προσχέδιο εμφανίζεται χωρίς δημόσια δημοσίευση. Αν λείπει το εταιρικό περιβάλλον, μην παρακάμπτετε την προειδοποίηση. Επιστρέψτε στον εξουσιοδοτημένο χώρο εργασίας. Δείτε την <a href="./draft-storage.html">αποθήκευση προσχεδίων</a>.</p><h2 id="βελτιωσεις-επεξεργαστη-στη-v0-7-10" tabindex="-1">Βελτιώσεις επεξεργαστή στη v0.7.10 <a class="header-anchor" href="#βελτιωσεις-επεξεργαστη-στη-v0-7-10" aria-label="Permalink to &quot;Βελτιώσεις επεξεργαστή στη v0.7.10&quot;">​</a></h2><p><strong>Κατάσταση: έκδοση staging ελεγμένη βάσει κώδικα.</strong> Σε συμβατό χώρο Website Studio:</p><ol><li>Επιλέξτε Edit για διάταξη ενοτήτων και Preview για έλεγχο χωρίς περιγράμματα επιλογής και αιωρούμενα εργαλεία επεξεργασίας.</li><li>Αναζητήστε έτοιμες ενότητες και εισαγάγετε μία μετά την επιλεγμένη ενότητα όπου χρειάζεται.</li><li>Ελέγξτε τα μενού κεφαλίδας και υποσέλιδου, το κουμπί CTA της κεφαλίδας και την εναλλαγή γλώσσας. Δοκιμάστε την πλοήγηση στην προεπισκόπηση.</li><li>Χρησιμοποιήστε <code>Ctrl/Cmd+S</code> για αποθήκευση, <code>Ctrl/Cmd+Z</code> για αναίρεση, <code>Ctrl/Cmd+Shift+Z</code> ή <code>Ctrl+Y</code> για επανάληψη και <code>Esc</code> για έξοδο από προεπισκόπηση ή αποεπιλογή. Επιβεβαιώστε την επιτυχία αποθήκευσης.</li><li>Ελέγξτε desktop, tablet, mobile και στενή οθόνη 320 px, συμπεριλαμβανομένων του μενού κινητού και των εργαλείων κράτησης.</li></ol><p>Η προεπισκόπηση δεν αποδεικνύει λειτουργία δημόσιας ιστοσελίδας. Το ανεξάρτητο kit περιλαμβάνει συμβατές βελτιώσεις· ελέγξτε χωριστά την εγκατεστημένη έκδοσή του. Δείτε <a href="./draft-storage.html">τοπικά προσχέδια</a>.</p>',19)])])}const f=a(s,[["render",l]]);export{b as __pageData,f as default};
